What did we just collect?

{
  // Real example values pulled from whatever's actually loaded (live class
  // data, or the synthetic placeholder before it's swapped in) — never
  // hardcoded illustrative examples, so this never goes stale.
  const take = (arr, n = 2) =&gt; {
    const uniq = [...new Set(arr)].filter(v =&gt; v !== null && v !== undefined && v !== '')
    if (!uniq.length) return "—"
    return uniq.slice(0, n).join(", ") + (uniq.length &gt; n ? ", …" : "")
  }
  const nameEx   = take(students)
  const rtEx     = take(data.map(d =&gt; `${d.reaction_time_ms} ms`))
  const deviceEx = take(data.map(d =&gt; d.device))
  const caffEx   = take(data.map(d =&gt; d.caffeine))
  const fingerEx = take(data.map(d =&gt; d.finger_mm !== null && d.finger_mm !== undefined ? `${d.finger_mm} mm` : null))

  return html`&lt;table style="width:100%;border-collapse:collapse;font-family:sans-serif;font-size:0.95em;"&gt;
  &lt;caption class="visually-hidden"&gt;This table grounds the discussion of variable types in what was actually just collected — name, reaction time, device, caffeine, and finger length — showing each one's type and scale, with real example values from the data.&lt;/caption&gt;
  &lt;thead&gt;
    &lt;tr style="background:#1a1a2e;color:white;"&gt;
      &lt;th scope="col" style="padding:12px 20px;text-align:left;"&gt;Variable&lt;/th&gt;
      &lt;th scope="col" style="padding:12px 20px;text-align:left;"&gt;Type&lt;/th&gt;
      &lt;th scope="col" style="padding:12px 20px;text-align:left;"&gt;Scale&lt;/th&gt;
      &lt;th scope="col" style="padding:12px 20px;text-align:left;"&gt;Example values&lt;/th&gt;
    &lt;/tr&gt;
  &lt;/thead&gt;
  &lt;tbody&gt;
    &lt;tr style="border-bottom:1px solid #eee;"&gt;
      &lt;td style="padding:12px 20px;font-weight:600;"&gt;Name&lt;/td&gt;
      &lt;td style="padding:12px 20px;"&gt;Categorical&lt;/td&gt;
      &lt;td style="padding:12px 20px;"&gt;Nominal&lt;/td&gt;
      &lt;td style="padding:12px 20px;color:#666;"&gt;${nameEx}&lt;/td&gt;
    &lt;/tr&gt;
    &lt;tr style="background:#fafafa;border-bottom:1px solid #eee;"&gt;
      &lt;td style="padding:12px 20px;font-weight:600;"&gt;Reaction time&lt;/td&gt;
      &lt;td style="padding:12px 20px;"&gt;Continuous&lt;/td&gt;
      &lt;td style="padding:12px 20px;"&gt;Ratio&lt;/td&gt;
      &lt;td style="padding:12px 20px;color:#666;"&gt;${rtEx}&lt;/td&gt;
    &lt;/tr&gt;
    &lt;tr style="border-bottom:1px solid #eee;"&gt;
      &lt;td style="padding:12px 20px;font-weight:600;"&gt;Device&lt;/td&gt;
      &lt;td style="padding:12px 20px;"&gt;Categorical&lt;/td&gt;
      &lt;td style="padding:12px 20px;"&gt;Nominal&lt;/td&gt;
      &lt;td style="padding:12px 20px;color:#666;"&gt;${deviceEx}&lt;/td&gt;
    &lt;/tr&gt;
    &lt;tr style="background:#fafafa;border-bottom:1px solid #eee;"&gt;
      &lt;td style="padding:12px 20px;font-weight:600;"&gt;Caffeine&lt;/td&gt;
      &lt;td style="padding:12px 20px;"&gt;Binary&lt;/td&gt;
      &lt;td style="padding:12px 20px;"&gt;Nominal&lt;/td&gt;
      &lt;td style="padding:12px 20px;color:#666;"&gt;${caffEx}&lt;/td&gt;
    &lt;/tr&gt;
    &lt;tr&gt;
      &lt;td style="padding:12px 20px;font-weight:600;"&gt;Finger length&lt;/td&gt;
      &lt;td style="padding:12px 20px;"&gt;Continuous&lt;/td&gt;
      &lt;td style="padding:12px 20px;"&gt;Ratio&lt;/td&gt;
      &lt;td style="padding:12px 20px;color:#666;"&gt;${fingerEx}&lt;/td&gt;
    &lt;/tr&gt;
  &lt;/tbody&gt;
&lt;/table&gt;`
}













Note


The type of variable determines which summaries and visualisations are meaningful. Taking a mean of Device is not just unhelpful — it is nonsense.

One student’s raw data

viewof selected_student = Inputs.select([null, ...students], {
  label: null,
  format: d =&gt; d === null ? "— select a student —" : d,
  value: null
})







student_data = selected_student
  ? data.filter(d =&gt; d.student_name === selected_student)
  : []







{
  if (!selected_student) return html`&lt;p style="color:#aaa;text-align:center;margin-top:60px;font-size:1.1em;"&gt;Select a student from the dropdown above.&lt;/p&gt;`

  const th = `&lt;thead&gt;&lt;tr style="background:#1a1a2e;color:white;"&gt;
    &lt;th scope="col" style="padding:11px 40px;text-align:center;font-size:0.95em;"&gt;Trial&lt;/th&gt;
    &lt;th scope="col" style="padding:11px 40px;text-align:center;font-size:0.95em;"&gt;Time (ms)&lt;/th&gt;
  &lt;/tr&gt;&lt;/thead&gt;`

  const rows = slice =&gt; slice.map(d =&gt;
    `&lt;tr style="border-bottom:1px solid #eee;"&gt;
      &lt;td style="padding:10px 40px;text-align:center;"&gt;${d.trial}&lt;/td&gt;
      &lt;td style="padding:10px 40px;text-align:center;font-weight:700;color:#457b9d;font-size:1.05em;"&gt;${d.reaction_time_ms}&lt;/td&gt;
    &lt;/tr&gt;`).join('')

  return html`&lt;div style="display:grid;grid-template-columns:1fr 1fr;gap:60px;width:75%;margin:24px auto 0;"&gt;
    &lt;table style="border-collapse:collapse;font-family:sans-serif;width:100%"&gt;
      &lt;caption class="visually-hidden"&gt;This table shows ${selected_student}'s own raw numbers before any summarising happens — trials one to five.&lt;/caption&gt;
      ${th}&lt;tbody&gt;${rows(student_data.slice(0,5))}&lt;/tbody&gt;
    &lt;/table&gt;
    &lt;table style="border-collapse:collapse;font-family:sans-serif;width:100%"&gt;
      &lt;caption class="visually-hidden"&gt;This table continues ${selected_student}'s own raw numbers — trials six to ten.&lt;/caption&gt;
      ${th}&lt;tbody&gt;${rows(student_data.slice(5,10))}&lt;/tbody&gt;
    &lt;/table&gt;
  &lt;/div&gt;`
}

Tidy data
Every row is one observation. Every column is one variable.

html`&lt;table style="width:100%;border-collapse:collapse;font-family:sans-serif;font-size:0.88em;margin-top:16px;"&gt;
  &lt;caption class="visually-hidden"&gt;This table shows what tidy format actually looks like — one row per trial, one column per variable — using the first five of ${data.length} real rows.&lt;/caption&gt;
  &lt;thead&gt;
    &lt;tr style="background:#1a1a2e;color:white;"&gt;
      &lt;th scope="col" style="padding:10px 18px;text-align:left;"&gt;student_name&lt;/th&gt;
      &lt;th scope="col" style="padding:10px 18px;text-align:left;"&gt;trial&lt;/th&gt;
      &lt;th scope="col" style="padding:10px 18px;text-align:left;"&gt;reaction_time_ms&lt;/th&gt;
      &lt;th scope="col" style="padding:10px 18px;text-align:left;"&gt;device&lt;/th&gt;
      &lt;th scope="col" style="padding:10px 18px;text-align:left;"&gt;caffeine&lt;/th&gt;
      &lt;th scope="col" style="padding:10px 18px;text-align:left;"&gt;finger_mm&lt;/th&gt;
    &lt;/tr&gt;
  &lt;/thead&gt;
  &lt;tbody&gt;
    ${data.slice(0,5).map((r,i) =&gt; `
      &lt;tr style="${i%2===1?'background:#fafafa;':''}border-bottom:1px solid #eee;"&gt;
        &lt;td style="padding:9px 18px;"&gt;${r.student_name}&lt;/td&gt;
        &lt;td style="padding:9px 18px;text-align:center;"&gt;${r.trial}&lt;/td&gt;
        &lt;td style="padding:9px 18px;text-align:right;font-weight:700;color:#457b9d;"&gt;${r.reaction_time_ms}&lt;/td&gt;
        &lt;td style="padding:9px 18px;"&gt;${r.device}&lt;/td&gt;
        &lt;td style="padding:9px 18px;"&gt;${r.caffeine || '—'}&lt;/td&gt;
        &lt;td style="padding:9px 18px;"&gt;${r.finger_mm ?? '—'}&lt;/td&gt;
      &lt;/tr&gt;`).join('')}
    &lt;tr&gt;&lt;td colspan="6" style="padding:9px 18px;color:#888;font-style:italic;font-size:0.9em;"&gt;… ${data.length} rows total (10 trials × ${students.length} students)&lt;/td&gt;&lt;/tr&gt;
  &lt;/tbody&gt;
&lt;/table&gt;`







This format makes filtering, grouping, and plotting straightforward. One student’s data = filter by student_name. One trial type = filter by trial. One device group = filter by device.

Frequencies and probabilities in our data
Task (paper) — Using the data we have generated, complete a frequency table for Device. What is the probability that a randomly selected student used a phone?


