One person’s trials

viewof selected_student_trials = Inputs.select([null, ...students], {
  label: null,
  format: d =&gt; d === null ? "— select a student —" : d,
  value: null
})







student_data_trials = selected_student_trials
  ? data.filter(d =&gt; d.student_name === selected_student_trials)
  : []







{
  if (!selected_student_trials) return html`&lt;p style="color:#aaa;text-align:center;margin-top:60px;font-size:1.1em;"&gt;
    Select a student from the dropdown above.&lt;/p&gt;`

  const vals = student_data_trials.map(d =&gt; d.reaction_time_ms)
  const lo   = d3.min(vals)
  const hi   = d3.max(vals)
  const pad  = Math.max(20, Math.round((hi - lo) * 0.15))

  return accessibleChart(Plot.plot({
    height: 550,
    marginLeft: 60,
    marginBottom: 40,
    x: { label: "Trial number", tickFormat: d =&gt; d },
    y: { label: "Reaction time (ms)", domain: [lo - pad, hi + pad] },
    marks: [
      Plot.line(student_data_trials, { x: "trial", y: "reaction_time_ms", stroke: "#ccc", strokeWidth: 1.5 }),
      Plot.dot(student_data_trials,  { x: "trial", y: "reaction_time_ms", fill: "#457b9d", r: 9,
                                tip: true, title: d =&gt; `Trial ${d.trial}: ${d.reaction_time_ms} ms` }),
    ]
  }), "This chart shows that one person's reaction time varies from trial to trial rather than staying fixed. It plots reaction time against trial number, one to ten, for the selected student.")
}

One person’s distribution

{
  if (!selected_student_trials) return html`&lt;p style="color:#aaa;text-align:center;margin-top:100px;font-size:1.1em;"&gt;
    Select a student on the previous slide.&lt;/p&gt;`

  const vals = student_data_trials.map(d =&gt; d.reaction_time_ms)

  return accessibleChart(Plot.plot({
    height: 580,
    marginLeft: 60,
    marginBottom: 40,
    x: { label: "Reaction time (ms)" },
    y: { label: "Count" },
    marks: [
      Plot.rectY(vals, Plot.binX({ y: "count" }, { x: d =&gt; d, thresholds: 6, fill: "#457b9d" })),
      Plot.ruleY([0]),
    ]
  }), "This chart shows that even ten trials from one person spread across a range rather than clustering on one value. It's a histogram of the selected student's ten reaction times, grouped into six bins.")
}

Pooled histogram

// Default "exclude above" threshold for the pooled histogram — the same
// 1.5×IQR fence used by the "Spotting the outlier" check. With real class
// data there's no guarantee there's only one extreme value, so defaulting
// this slider to "show everything" can leave the first view of this chart
// completely unreadable (every bar compressed against the axis). Starting
// at the fence instead gives a sensible first view, with the full range
// still one drag away.
pool_fence = {
  const vals = data.map(d =&gt; d.reaction_time_ms)
  const sorted = [...vals].sort((a, b) =&gt; a - b)
  const q1 = d3.quantile(sorted, 0.25)
  const q3 = d3.quantile(sorted, 0.75)
  const iqr = q3 - q1
  return Math.min(Math.ceil(pool_max / 10) * 10 + 10, Math.ceil((q3 + 1.5 * iqr) / 10) * 10)
}







viewof hist_controls = {
  const thrMax = Math.ceil(pool_max / 10) * 10 + 10
  const f = html`&lt;div style="display:flex;align-items:center;gap:24px;flex-wrap:wrap;
                              font-size:13px;font-family:'Helvetica Neue',sans-serif;
                              padding:6px 2px;color:#333;"&gt;
    &lt;label style="display:flex;align-items:center;gap:8px;"&gt;
      &lt;span style="color:#666;white-space:nowrap;"&gt;Bin width&lt;/span&gt;
      &lt;input type="range" name="bin_width" min="10" max="80" step="10" value="30"
             style="width:100px;cursor:pointer;accent-color:#457b9d;"&gt;
      &lt;span id="bw-label" style="font-weight:600;min-width:34px;color:#457b9d;"&gt;30 ms&lt;/span&gt;
    &lt;/label&gt;
    &lt;label style="display:flex;align-items:center;gap:8px;"&gt;
      &lt;span style="color:#e63946;white-space:nowrap;font-weight:600;"&gt;Exclude above&lt;/span&gt;
      &lt;input type="range" name="threshold" min="${pool_min}" max="${thrMax}" step="10" value="${pool_fence}"
             style="width:110px;cursor:pointer;accent-color:#e63946;"&gt;
      &lt;span id="thr-label" style="font-weight:600;min-width:40px;color:#e63946;"&gt;${pool_fence &gt;= thrMax ? 'All' : pool_fence + ' ms'}&lt;/span&gt;
    &lt;/label&gt;
    &lt;label style="display:flex;align-items:center;gap:6px;cursor:pointer;"&gt;
      &lt;input type="checkbox" name="show_mean" checked style="cursor:pointer;accent-color:#e63946;"&gt; Mean
    &lt;/label&gt;
    &lt;label style="display:flex;align-items:center;gap:6px;cursor:pointer;"&gt;
      &lt;input type="checkbox" name="show_median" style="cursor:pointer;accent-color:#f4a261;"&gt; Median
    &lt;/label&gt;
    &lt;label style="display:flex;align-items:center;gap:6px;cursor:pointer;"&gt;
      &lt;input type="checkbox" name="show_kde" style="cursor:pointer;accent-color:#2d6a4f;"&gt; KDE
    &lt;/label&gt;
    &lt;label style="display:flex;align-items:center;gap:6px;cursor:pointer;"&gt;
      &lt;input type="checkbox" name="show_pct" style="cursor:pointer;accent-color:#333;"&gt; Show as %
    &lt;/label&gt;
  &lt;/div&gt;`

  const bwRange  = f.querySelector('[name=bin_width]')
  const bwLabel  = f.querySelector('#bw-label')
  const thrRange = f.querySelector('[name=threshold]')
  const thrLabel = f.querySelector('#thr-label')

  bwRange.addEventListener('input', () =&gt; {
    bwLabel.textContent = bwRange.value + ' ms'
    f.dispatchEvent(new CustomEvent('input'))
  })
  thrRange.addEventListener('input', () =&gt; {
    thrLabel.textContent = +thrRange.value &gt;= thrMax ? 'All' : thrRange.value + ' ms'
    f.dispatchEvent(new CustomEvent('input'))
  })
  f.querySelectorAll('input[type=checkbox]').forEach(cb =&gt;
    cb.addEventListener('change', () =&gt; f.dispatchEvent(new CustomEvent('input')))
  )
  Object.defineProperty(f, 'value', { get() { return {
    bin_width:  +f.querySelector('[name=bin_width]').value,
    threshold:  +f.querySelector('[name=threshold]').value,
    show_mean:   f.querySelector('[name=show_mean]').checked,
    show_median: f.querySelector('[name=show_median]').checked,
    show_kde:    f.querySelector('[name=show_kde]').checked,
    show_pct:    f.querySelector('[name=show_pct]').checked,
  }}})
  return f
}







{
  // Generic "shrink on reveal" wiring, used by every chart wrapped as
  // `:::: {.shrink-on-reveal data-frag="some-fragment-id" style="--large-height:...;--small-height:...;--shrink-scale:..."}`
  // (see the Pooled histogram slide below for the first example). Each chart
  // renders large while its named fragment is hidden, then shrinks smoothly
  // to make room the moment that fragment is revealed. Sizes live entirely
  // in each wrapper's own inline style — this cell only handles show/hide,
  // once, for every wrapper on the page, so adding a new chart to this
  // pattern never means touching this cell.
  const wrapperFor = (fragId) =&gt; document.querySelector(`.shrink-on-reveal[data-frag="${fragId}"]`)

  // Sets each wrapper's correct starting state immediately, including on a
  // reload or direct navigation to a slide whose fragment is already shown
  // — matters because this cell (no reactive deps) only runs once, at load.
  document.querySelectorAll('.shrink-on-reveal[data-frag]').forEach(el =&gt; {
    const frag = document.getElementById(el.dataset.frag)
    el.classList.toggle('is-small', !!frag?.classList.contains('visible'))
  })

  Reveal.on('fragmentshown', (event) =&gt; {
    wrapperFor(event.fragment.id)?.classList.add('is-small')
  })
  Reveal.on('fragmenthidden', (event) =&gt; {
    wrapperFor(event.fragment.id)?.classList.remove('is-small')
  })
}









{
  const thr      = hist_controls.threshold
  const thrMax   = Math.ceil(pool_max / 10) * 10 + 10
  const filtered = data.filter(d =&gt; d.reaction_time_ms &lt;= thr)
  const vals     = filtered.map(d =&gt; d.reaction_time_ms)
  const mu       = d3.mean(vals)
  const med      = d3.median(vals)
  const sigma    = d3.deviation(vals)
  const excluded = data.length - filtered.length
  const bw       = hist_controls.bin_width
  const pct      = hist_controls.show_pct

  const pad  = Math.max(20, Math.round((d3.max(vals) - d3.min(vals)) * 0.1))
  const xmin = Math.floor((d3.min(vals) - pad) / 10) * 10
  const xmax = Math.ceil((thr + pad) / 10) * 10

  // KDE — Epanechnikov kernel, Silverman's bandwidth
  // Absolute mode scales density to expected count per bin; relative mode
  // scales it to the same proportion-per-bin units as the "proportion" reducer.
  const h = sigma * 1.06 * Math.pow(vals.length, -0.2)
  const kdePoints = d3.range(xmin, xmax, 2).map(x =&gt; {
    const density = d3.mean(vals, v =&gt; {
      const u = (x - v) / h
      return Math.abs(u) &lt;= 1 ? 0.75 * (1 - u * u) / h : 0
    })
    return { x, y: pct ? density * bw : density * filtered.length * bw }
  })

  const chartLabel = `This chart shows how bin width and where you cut off outliers change a histogram's apparent shape. Currently: bins ${bw} ms wide` +
    (excluded &gt; 0 ? `, with ${excluded} value${excluded &gt; 1 ? 's' : ''} above ${thr} ms excluded` : ", with no values excluded") +
    `. The class's reaction times are right-skewed: most values cluster at the low end with a long tail of slower times.` +
    (hist_controls.show_mean ? ` The mean is ${mu.toFixed(1)} ms.` : "") +
    (hist_controls.show_median ? ` The median is ${med.toFixed(1)} ms.` : "") +
    (hist_controls.show_kde ? " A smoothed density curve is overlaid on the bars." : "")

  // 480 = this chart's "large" (fragment-still-hidden) native render size.
  // The CSS-scaled "small" size (330, matching the chart's original height)
  // is reached by scaling down by exactly the --shrink-scale set on the
  // wrapping .shrink-on-reveal div above, so the revealed state looks
  // identical to how this chart always looked before this pattern existed.
  const svg = Plot.plot({
    height: 480,
    marginLeft: 55,
    marginBottom: 32,
    x: { label: "Reaction time (ms)", domain: [xmin, xmax] },
    y: pct
      ? { label: "% of trials", percent: true }
      : { label: "Count" },
    marks: [
      Plot.rectY(filtered,
        Plot.binX({ y: pct ? "proportion" : "count" },
          { x: "reaction_time_ms", thresholds: d3.range(xmin, xmax + bw, bw),
            fill: "#457b9d", fillOpacity: 0.75 })),
      Plot.ruleX([0]),
      hist_controls.show_mean   ? Plot.ruleX([mu],  { stroke: "#e63946", strokeWidth: 2.5,
                             strokeDasharray: "6,4",
                             tip: true, title: () =&gt; `Mean: ${mu.toFixed(1)} ms` }) : null,
      hist_controls.show_median ? Plot.ruleX([med], { stroke: "#f4a261", strokeWidth: 2.5,
                             strokeDasharray: "6,4",
                             tip: true, title: () =&gt; `Median: ${med.toFixed(1)} ms` }) : null,
      hist_controls.show_kde    ? Plot.line(kdePoints, { x: "x", y: "y",
