  const stageForId = { 'frag-range': 'range', 'frag-sd': 'sd', 'frag-iqr': 'iqr', 'frag-90-10': '90-10' }
  const order = ['range', 'sd', 'iqr', '90-10']

  const handler = (event) =&gt; {
    const stage = event.fragment && stageForId[event.fragment.id]
    if (!stage) return
    if (event.type === 'fragmentshown') {
      mutable spreadStage = stage
    } else {
      const i = order.indexOf(stage)
      mutable spreadStage = i &gt; 0 ? order[i - 1] : 'none'
    }
  }
  Reveal.addEventListener('fragmentshown', handler)
  Reveal.addEventListener('fragmenthidden', handler)
  invalidation.then(() =&gt; {
    Reveal.removeEventListener('fragmentshown', handler)
    Reveal.removeEventListener('fragmenthidden', handler)
  })
  return html`&lt;span&gt;&lt;/span&gt;`
