    sd:     `one standard deviation either side of the mean is shaded, from ${(mu-sig).toFixed(0)} to ${(mu+sig).toFixed(0)} ms`,
    iqr:    `the interquartile range is shaded, from the 25th percentile ${q1.toFixed(0)} ms to the 75th percentile ${q3.toFixed(0)} ms`,
    '90-10': `the middle 80% is shaded, from the 10th percentile ${p10.toFixed(0)} ms to the 90th percentile ${p90.toFixed(0)} ms`,
