Spotting the outlier

// Real outlier test — Tukey's 1.5×IQR fence, the same rule taught in the
// "Task — compare two box plots" instructions box and used by every other
// box-plot chart in this deck. With real class data there's no guarantee
// the largest value is actually separated from the rest, so this decides
// whether the chart below is honest to call it "the outlier" — rather than
// always pointing an arrow at whatever the max happens to be.
outlier_check = {
  const vals    = data.map(d =&gt; d.reaction_time_ms)
  const sorted  = [...vals].sort((a, b) =&gt; a - b)
  const q1      = d3.quantile(sorted, 0.25)
  const q3      = d3.quantile(sorted, 0.75)
  const iqr     = q3 - q1
  const fenceHi = q3 + 1.5 * iqr
  const maxVal  = d3.max(vals)
  return { maxVal, fenceHi, isOutlier: maxVal &gt; fenceHi }
}









{
  const vals   = data.map(d =&gt; d.reaction_time_ms)
  const maxVal = outlier_check.maxVal
  const pad  = Math.max(20, Math.round((d3.max(vals) - d3.min(vals)) * 0.1))
  const xmin = Math.floor((d3.min(vals) - pad) / 10) * 10
  const xmax = Math.ceil((maxVal + pad) / 10) * 10
  const bw   = 30

  const bins = d3.bin().domain([xmin, xmax]).thresholds(d3.range(xmin, xmax + bw, bw))(vals)
  const maxBinCount = d3.max(bins, b =&gt; b.length)
  const topBin = bins.find(b =&gt; maxVal &gt;= b.x0 && maxVal &lt; b.x1) ?? bins[bins.length - 1]
  const labelY = maxBinCount + Math.max(2, Math.round(maxBinCount * 0.35))

  const marks = [
    Plot.rectY(bins, { x1: "x0", x2: "x1", y: "length", fill: "#457b9d", fillOpacity: 0.75 }),
    Plot.ruleX([0]),
  ]
  if (outlier_check.isOutlier) {
    marks.push(
      Plot.arrow([{ x1: maxVal, y1: labelY, x2: maxVal, y2: topBin.length + 0.3 }],
                 { x1: "x1", y1: "y1", x2: "x2", y2: "y2",
                   stroke: "#e63946", strokeWidth: 2.5, headLength: 10, insetEnd: 2 }),
      Plot.text([{ x: maxVal, y: labelY, label: `Highest: ${maxVal.toFixed(0)} ms` }],
                { x: "x", y: "y", text: "label", dy: -10, fill: "#e63946",
                  fontSize: 13, fontWeight: 600 }),
    )
  }

  const chartLabel = outlier_check.isOutlier
    ? `This chart highlights the single most extreme reaction time in the dataset, to set up the question of what to do with it. An arrow points to ${maxVal.toFixed(0)} ms, the point furthest from the rest of the distribution.`
    : `This chart shows the pooled distribution of reaction times. No value is far enough from the rest to count as a statistical outlier by the 1.5 times IQR rule — the highest value, ${maxVal.toFixed(0)} ms, sits within the expected spread.`

  return accessibleChart(Plot.plot({
