                            fill: d =&gt; colours[d.group], fillOpacity: 0.55,
                            stroke: d =&gt; colours[d.group], strokeWidth: 2 }),
      Plot.tickX(grouped, { x: "q2", y: "group", insetTop: 14, insetBottom: 14, stroke: "white", strokeWidth: 3 }),
      Plot.dot(grouped,   { x: "mean", y: "group", fill: d =&gt; colours[d.group], stroke: "white",
                            strokeWidth: 1, r: 6, symbol: "diamond" }),
      Plot.dot(outliers,  { x: "reaction_time_ms", y: "device",
                            stroke: d =&gt; colours[d.device], fill: "white", r: 5, strokeWidth: 1.5 }),
    ]
  }), `This chart introduces the box plot as a compact way to summarise and compare two groups' distributions, using phone versus laptop reaction times as the example. Phone users have a median of ${grouped[0].q2.toFixed(0)} ms and laptop users ${grouped[1].q2.toFixed(0)} ms; each box spans the interquartile range with the median marked by a white tick and the mean by a diamond, whiskers reach the furthest non-outlier point, and open circles mark outliers beyond that.`)
}









Box = IQR · Line = median · Diamond = mean · Whiskers = furthest point within 1.5×IQR of the box · Open circles = outliers beyond that.

Our data, and its log — the answer

{
  const RT_FILTER_CUTOFF = 800
  const rtFiltered = rt.filter(d =&gt; d &lt; RT_FILTER_CUTOFF)
  const logRt = rtFiltered.map(Math.log)
  const logDomain = d3.extent(logRt)

  const p1 = accessibleChart(Plot.plot({
    height: 380, width: 420,
    x: { label: "Reaction time (ms)", domain: [0, RT_FILTER_CUTOFF] },
    y: { label: "% of trials", percent: true },
    marks: [
      Plot.rectY(rtFiltered, Plot.binX({ y: "proportion" },
        { x: d =&gt; d, thresholds: 20, fill: "#457b9d", fillOpacity: 0.8 })),
      Plot.ruleX([0]),
    ]
  }), "This chart tests the log-normal claim by showing the actual shape of the class's raw reaction times, for comparison with their log beside it. Trials of 800 milliseconds or more are set aside first, since a handful of much slower trials would otherwise dominate the shape; among the rest, the shape is right-skewed.")
  const p2 = accessibleChart(Plot.plot({
    height: 380, width: 420,
    x: { label: "log(reaction time)", domain: logDomain },
    y: { label: "% of trials", percent: true },
    marks: [
      Plot.rectY(logRt, Plot.binX({ y: "proportion" },
        { x: d =&gt; d, thresholds: 20, fill: "#2d6a4f", fillOpacity: 0.8 })),
      Plot.ruleX([0]),
    ]
  }), "This chart tests the log-normal claim by showing the class's reaction times after a log transform, for comparison with the raw shape beside it. The shape is closer to symmetric and bell-shaped, supporting the log-normal claim.")

  return html`&lt;div style="display:flex;gap:24px;justify-content:center;"&gt;${p1}${p2}&lt;/div&gt;`
}






Raw reaction times (blue) are right-skewed with a long tail. Their log (green) looks closer to symmetric and bell-shaped — exactly what the log-normal claim predicts.
